text:
Caveman mode: **full**

---

Three parts: class component, fallback UI, usage.

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Log here — swap console for Sentry/Datadog/etc
    console.error("[ErrorBoundary]", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });

    this.props.onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      return fallback
        ? fallback(error, this.reset)
        : <DefaultFallback error={error} reset={this.reset} />;
    }

    return children;
  }
}
```

```tsx
// DefaultFallback.tsx
interface FallbackProps {
  error: Error;
  reset: () => void;
}

function DefaultFallback({ error, reset }: FallbackProps) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "8px",
    background: "#fef2f2",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  title:  { margin: "0 0 .5rem", color: "#b91c1c" },
  message: { fontSize: ".85rem", color: "#7f1d1d", whiteSpace: "pre-wrap" as const },
  button: {
    marginTop: "1rem",
    padding: ".5rem 1.25rem",
    background: "#b91c1c",
    color: "#fff",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
  },
} as const;
```

```tsx
// Usage
import { ErrorBoundary } from "./ErrorBoundary";

// Default fallback
<ErrorBoundary onError={(err, info) => myLogger.capture(err, info)}>
  <RiskyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary
  fallback={(error, reset) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={reset}>Retry</button>
    </div>
  )}
>
  <RiskyComponent />
</ErrorBoundary>
```

---

Key decisions:

- **`getDerivedStateFromError`** — static, pure, set error state. No side effects here.
- **`componentDidCatch`** — side effects live here (logging). Both needed, different jobs.
- **`reset` clears state** — React re-mount children fresh. If same bug persist, boundary catch again.
- **`fallback` prop** — render prop pattern. Full control, no need to subclass.

Watch: error boundaries no catch async errors, event handlers, or errors in boundary itself. For async, use `window.onerror` or try/catch + `setState`.
